CREATE TABLE `products` (
  `name` varchar(500) NOT NULL,
  `description` text,
  `sku` varchar(100) DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `brand` varchar(255) DEFAULT NULL,
  `image_url` varchar(1000) DEFAULT NULL,
  `target_price` float DEFAULT NULL,
  `min_price_threshold` float DEFAULT NULL,
  `max_price_threshold` float DEFAULT NULL,
  `user_id` int NOT NULL,
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_products_sku` (`sku`),
  KEY `idx_product_user_category` (`user_id`,`category`),
  KEY `ix_products_user_id` (`user_id`),
  KEY `idx_product_sku_user` (`sku`,`user_id`),
  KEY `ix_products_brand` (`brand`),
  KEY `ix_products_id` (`id`),
  KEY `ix_products_category` (`category`),
  KEY `ix_products_name` (`name`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
