--
-- Table structure for table `scraping_jobs`
--

DROP TABLE IF EXISTS `scraping_jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scraping_jobs` (
  `competitor_id` int NOT NULL,
  `product_id` int DEFAULT NULL,
  `status` enum('PENDING','RUNNING','COMPLETED','FAILED','CANCELLED') NOT NULL,
  `job_type` varchar(50) NOT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `error_message` text,
  `result_data` json DEFAULT NULL,
  `celery_task_id` varchar(255) DEFAULT NULL,
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_scraping_jobs_id` (`id`),
  KEY `ix_scraping_jobs_product_id` (`product_id`),
  KEY `ix_scraping_jobs_competitor_id` (`competitor_id`),
  KEY `ix_scraping_jobs_celery_task_id` (`celery_task_id`),
  CONSTRAINT `scraping_jobs_ibfk_1` FOREIGN KEY (`competitor_id`) REFERENCES `competitors` (`id`),
  CONSTRAINT `scraping_jobs_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

